```620:638:/home/admin/frontend/src/pages/ParentPortal.vue
const login = async () => {
  loginError.value = '';
  if (!loginForm.value.Name?.trim() || !loginForm.value.Phone?.trim()) {
    loginError.value = '請輸入學生姓名和手機號碼';
    return;
  }
  if (loginLoading.value) return;
  loginLoading.value = true;
  try {
    const result = await parentLogin(loginForm.value);
    token.value = result.token;
    localStorage.setItem(tokenKey, result.token);
    if (result.students) setStudents(result.students);
    await loadDashboard();
  } catch (error) {
    loginError.value = error.message || '登入失敗，請確認學生姓名及手機號碼是否正確';
  } finally {
    loginLoading.value = false;
  }
};
```

### B. LINE: LIFF profile `userId` (not phone on the wire for LINE login)

```641:658:/home/admin/frontend/src/pages/ParentPortal.vue
const loginWithLine = async () => {
  loginError.value = '';
  try {
    if (!window.liff) {
      loginError.value = '請從 LINE 應用程式開啟此頁面';
      return;
    }
    if (!window.liff.isLoggedIn()) {
      // User not logged in to LIFF — trigger LINE login
      window.liff.login();
      return;
    }
    const profile = await window.liff.getProfile();
    const result = await parentLoginLine(profile.userId);
    token.value = result.token;
    localStorage.setItem(tokenKey, result.token);
    if (result.students) setStudents(result.students);
    await loadDashboard();
```

### C. API payload (frontend)

`/home/admin/frontend/src/api.js` — phone/name vs `line_user_id`:

```6:20:/home/admin/frontend/src/api.js
export async function parentLogin(credentials) {
  const payload = { Phone: String(credentials.Phone || '').trim() };
  const sid = Number(credentials.StudentID);
  const name = String(credentials.Name || '').trim();
  if (sid > 0) payload.StudentID = sid;
  if (name) payload.Name = name;
  const res = await fetch(`${API_BASE}/parent/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data?.message || '登入失敗');
  return { token: data.token, student: data.student, students: data.students || null };
}
```

```32:40:/home/admin/frontend/src/api.js
export async function parentLoginLine(lineUserId) {
  const res = await fetch(`${API_BASE}/parent/login-line`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ line_user_id: lineUserId }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data?.message || 'LINE 登入失敗');
  return { token: data.token, student: data.student, students: data.students || null };
}
```

### D. Backend: phone/name (optional `StudentID`) vs LINE `line_user_id`

`/home/admin/backend/app/Http/Controllers/ParentPortalController.php` — validates `StudentID` **or** `Name` + required `Phone`, normalizes phone digits, matches student; session token via `createSession`:

```26:85:/home/admin/backend/app/Http/Controllers/ParentPortalController.php
    public function login(Request $request)
    {
        $data = $request->validate([
            'StudentID' => 'nullable|integer',
            'Name' => 'nullable|string|max:64',
            'Phone' => 'required|string|max:20',
        ]);

        $phoneNorm = $this->normalizePhone($data['Phone']);
        // ...
        if (!empty($data['StudentID']) && (int) $data['StudentID'] > 0) {
            $student = Student::find((int) $data['StudentID']);
            // ...
        } elseif (!empty(trim($data['Name'] ?? ''))) {
            $name = trim($data['Name']);
            $candidates = Student::whereRaw('TRIM(name) = ?', [$name])->get();
            foreach ($candidates as $s) {
                if (!empty($s->Phone) && $this->normalizePhone($s->Phone) === $phoneNorm) {
                    $student = $s;
                    break;
                }
            }
            // ...
        }
        // ...
        $result = $this->createSession($student);

        // Find siblings: other students with the same phone number
        $siblings = Student::where('id', '!=', $student->id)
            ->get()
            ->filter(fn ($s) => !empty($s->Phone) && $this->normalizePhone($s->Phone) === $phoneNorm);
        $allStudents = collect([['id' => $student->id, 'name' => $student->name]])
            ->concat($siblings->map(fn ($s) => ['id' => $s->id, 'name' => $s->name]))
            ->values();
        if ($allStudents->count() > 1) {
            $result['students'] = $allStudents;
        }

        return response()->json($result);
    }
```

LINE login looks up **all** `student_id`s bound to that LINE user, errors if none, then issues a session for the **first** student and returns the full bound list:

```119:137:/home/admin/backend/app/Http/Controllers/ParentPortalController.php
    public function loginWithLine(Request $request)
    {
        $data = $request->validate([
            'line_user_id' => 'required|string',
        ]);

        $studentIds = StudentLineBinding::where('line_user_id', $data['line_user_id'])
            ->pluck('student_id');
        $students = $studentIds->isNotEmpty()
            ? Student::whereIn('id', $studentIds)->get()
            : collect();
        if ($students->isEmpty()) {
            return response()->json(['message' => '尚未綁定學生帳號（此入口僅供家長/學生）。請透過 LINE 官方帳號輸入「綁定 學生姓名 手機號碼」完成綁定'], 404);
        }

        // Create session for the first student (frontend can switch later)
        $result = $this->createSession($students->first());
        $result['students'] = $students->map(fn ($s) => ['id' => $s->id, 'name' => $s->name])->values();
        return response()->json($result);
    }
```

Token is a random string stored as SHA-256 in `ParentSession` (Bearer token):

```589:606:/home/admin/backend/app/Http/Controllers/ParentPortalController.php
    private function createSession(Student $student): array
    {
        $token = Str::random(48);
        $hash = hash('sha256', $token);

        ParentSession::create([
            'StudentID' => $student->id,
            'TokenHash' => $hash,
            'ExpiresAt' => Carbon::now()->addDays(30),
        ]);

        return [
            'token' => $token,
            'student' => [
                'id'   => $student->id,
                'name' => $student->name,
            ],
        ];
    }
```

